from itsdangerous import Serializer


def deserialize_without_verification(secret_key: str, signed_string: str, salt: str | None = None) -> dict[str, bool | str | None]:
    """Deserializes a signed string without verifying the signature. secret_key: The secret key used for signing and verification, signed_string: The signed string to deserialize without verification, salt: Salt to use for the serializer. Returns a dictionary with 'signature_valid' (bool) and 'payload' (str or None)."""
    try:
        serializer = Serializer(secret_key, salt=salt.encode() if salt else None)
        signature_valid, payload = serializer.loads_unsafe(signed_string)
        return {"signature_valid": signature_valid, "payload": str(payload) if payload is not None else None}
    except Exception as e:
        raise ValueError(f"Failed to deserialize string: {str(e)}")
